<?php
declare(strict_types=1);require dirname(__DIR__).'/vendor/autoload.php';use Ogpn\Bot\Bootstrap;if($argc<5){fwrite(STDERR,"Usage: php bin/create-worker.php ID PLATFORM ROLE CAPACITY\n");exit(2);}[$x,$id,$platform,$role,$capacity]=$argv;$token=bin2hex(random_bytes(32));$perms=$role==='discovery'?['worker.plan','discovery.claim','discovery.ingest']:['worker.plan','scan.claim','scan.ingest'];$s=Bootstrap::pdo()->prepare('INSERT INTO workers(worker_id,platform,preferred_role,capacity,token_hash,permissions) VALUES(?,?,?,?,?,?) ON DUPLICATE KEY UPDATE platform=VALUES(platform),preferred_role=VALUES(preferred_role),capacity=VALUES(capacity),token_hash=VALUES(token_hash),permissions=VALUES(permissions),enabled=1');$s->execute([$id,$platform,$role,$capacity,hash('sha256',$token),json_encode($perms)]);echo "Worker: $id\nToken (affiché une seule fois): $token\n";
